create or replace function public.life_undo_plan(p_idempotency_key text) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v public.life_plan_requests%rowtype; v_id text; v_count int:=0; begin select * into v from public.life_plan_requests where idempotency_key=p_idempotency_key and user_id=auth.uid() for update; if not found then raise exception 'plan_request_not_found'; end if; if coalesce((v.result->>'undone')::boolean,false) then return v.result; end if; for v_id in select jsonb_array_elements_text(v.result->'ids') loop delete from public.life_items where id=v_id and user_id=auth.uid() and status='planned'; if found then v_count:=v_count+1; end if; end loop; v.result:=v.result||jsonb_build_object('undone',true,'undone_count',v_count,'undone_at',now()); update public.life_plan_requests set result=v.result where idempotency_key=p_idempotency_key and user_id=auth.uid(); return v.result; end; $$;